{"title":"DEV — 챕터 진행 분포","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Per-user max cleared chapter — live query on dev-example-project-game-user-cohort",
  "width": "container",
  "height": "container",
  "padding": {
    "top": 72,
    "bottom": 50,
    "left": 44,
    "right": 24
  },
  "data": [
    {
      "name": "es_agg",
      "url": {
        "%context%": true,
        "%timefield%": "first_seen",
        "index": "dev-example-project-game-user-cohort",
        "body": {
          "size": 0,
          "aggs": {
            "chapters": {
              "terms": {
                "field": "max_cleared_chapter",
                "missing": 0,
                "size": 100,
                "order": {
                  "_key": "asc"
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.chapters.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.key",
          "as": "chapter"
        },
        {
          "type": "formula",
          "expr": "datum.doc_count",
          "as": "user_count"
        },
        {
          "type": "joinaggregate",
          "fields": [
            "user_count"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "total_users"
          ]
        },
        {
          "type": "formula",
          "expr": "datum.total_users > 0 ? round((datum.user_count / datum.total_users) * 1000) / 10 : 0",
          "as": "pct"
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "totalUsers",
      "update": "length(data('es_agg')) > 0 ? data('es_agg')[0].total_users : 0"
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "band",
      "range": "width",
      "padding": 0.15,
      "domain": {
        "data": "es_agg",
        "field": "chapter",
        "sort": {
          "field": "chapter",
          "op": "min",
          "order": "ascending"
        }
      }
    },
    {
      "name": "y",
      "type": "linear",
      "range": "height",
      "nice": true,
      "zero": true,
      "domain": {
        "data": "es_agg",
        "field": "user_count"
      }
    }
  ],
  "axes": [
    {
      "scale": "x",
      "orient": "bottom",
      "title": "최고 클리어 챕터",
      "labelAngle": 0
    },
    {
      "scale": "y",
      "orient": "left",
      "title": "유저 수",
      "tickMinStep": 1
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {
        "enter": {
          "x": {
            "value": -44
          },
          "y": {
            "value": -54
          },
          "text": {
            "signal": "'전체 유저: ' + format(totalUsers, ',d') + '명'"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": "normal"
          },
          "fill": {
            "value": "#535766"
          },
          "baseline": {
            "value": "middle"
          },
          "align": {
            "value": "left"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "es_agg"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "chapter"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "y": {
            "scale": "y",
            "field": "user_count"
          },
          "y2": {
            "scale": "y",
            "value": 0
          },
          "fill": {
            "value": "#54B399"
          },
          "cornerRadiusTopLeft": {
            "value": 2
          },
          "cornerRadiusTopRight": {
            "value": 2
          },
          "tooltip": {
            "signal": "{ 'Chapter': datum.chapter, 'Users': datum.user_count, 'Share': datum.pct + '%' }"
          }
        },
        "hover": {
          "fill": {
            "value": "#347669"
          }
        },
        "update": {
          "fill": {
            "value": "#54B399"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "es_agg"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "chapter",
            "band": 0.5
          },
          "y": {
            "scale": "y",
            "field": "user_count",
            "offset": -16
          },
          "text": {
            "field": "user_count"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "bottom"
          },
          "fontSize": {
            "value": 11
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "value": "#1A1D23"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "es_agg"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "chapter",
            "band": 0.5
          },
          "y": {
            "scale": "y",
            "field": "user_count",
            "offset": -3
          },
          "text": {
            "signal": "datum.pct + '%'"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "bottom"
          },
          "fontSize": {
            "value": 9
          },
          "fill": {
            "value": "#6B7280"
          }
        }
      }
    }
  ]
}"}}

