{"title":"결제 Top 50 유저 (누적)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "width": 250,
  "height": {
    "step": 22
  },
  "padding": {
    "left": 8,
    "top": 0,
    "right": 8,
    "bottom": 4
  },
  "config": {
    "kibana": {
      "renderer": "svg"
    },
    "view": {
      "stroke": null
    }
  },
  "data": {
    "url": {
      "index": "dev-example-project-game",
      "body": {
        "size": 0,
        "aggs": {
          "claims": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.requestPath.keyword": "/internal/iap/deliver"
                    }
                  },
                  {
                    "term": {
                      "data.statusCode": 200
                    }
                  },
                  {
                    "match_phrase": {
                      "data.requestBody": "\"payEnv\":\"test\""
                    }
                  }
                ]
              }
            },
            "aggs": {
              "topUsers": {
                "terms": {
                  "field": "data.userId",
                  "size": 5000,
                  "order": {
                    "orders": "desc"
                  }
                },
                "aggs": {
                  "country": {
                    "terms": {
                      "field": "data.countryCode.keyword",
                      "size": 1
                    }
                  },
                  "orders": {
                    "cardinality": {
                      "field": "iap_order_id",
                      "precision_threshold": 40000
                    }
                  },
                  "orderList": {
                    "terms": {
                      "field": "iap_order_id",
                      "size": 5000
                    },
                    "aggs": {
                      "usd": {
                        "max": {
                          "field": "usd_list_price"
                        }
                      }
                    }
                  },
                  "usdSum": {
                    "sum_bucket": {
                      "buckets_path": "orderList>usd"
                    }
                  }
                }
              }
            }
          }
        },
        "runtime_mappings": {
          "iap_order_id": {
            "type": "keyword",
            "script": {
              "source": "def b = params._source?.data?.requestBody; if (b == null) return; String s = b.toString(); int i = s.indexOf('\"orderId\":'); if (i < 0) return; int p = i + 10; while (p < s.length() && s.charAt(p) == (char)' ') p++; int st = p; while (p < s.length() && Character.isDigit(s.charAt(p))) p++; if (p > st) emit(s.substring(st, p));"
            }
          },
          "usd_list_price": {
            "type": "double",
            "script": {
              "source": "def b = params._source?.data?.requestBody; if (b == null) return; String s = b.toString(); int i = s.indexOf('\"marketProductId\":\"'); if (i < 0) return; int st = i + 19; int e = s.indexOf('\"', st); if (e < 0) return; String pid = s.substring(st, e); int k = pid.lastIndexOf('pack.'); if (k < 0) return; try { emit(Double.parseDouble(pid.substring(k + 5))); } catch (Exception ex) {}"
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.claims.topUsers.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.orders.value",
      "as": "doc_count"
    },
    {
      "calculate": "datum.usdSum.value",
      "as": "usdValue"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "usdValue",
          "order": "descending"
        },
        {
          "field": "doc_count",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 50"
    },
    {
      "calculate": "toString(datum.rank)",
      "as": "rankText"
    },
    {
      "calculate": "toString(datum.key)",
      "as": "userId"
    },
    {
      "calculate": "length(datum.country.buckets) > 0 ? datum.country.buckets[0].key : '-'",
      "as": "cc"
    },
    {
      "calculate": "format(datum.doc_count, ',') + '건'",
      "as": "cntText"
    },
    {
      "calculate": "format(datum.usdSum.value, '$,.2f')",
      "as": "usdText"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rule",
        "x": 0,
        "color": "#69707d",
        "strokeWidth": 1,
        "x2": 234,
        "yOffset": 11,
        "opacity": 0.4
      },
      "data": {
        "values": [
          {
            "rank": 0
          }
        ]
      },
      "encoding": {
        "y": {
          "field": "rank",
          "type": "ordinal",
