        "y": {
          "expr": "height - 14"
        }
      },
      "encoding": {
        "text": {
          "field": "usd",
          "type": "nominal"
        }
      }
    }
  ],
  "config": {
    "view": {
      "strokeWidth": 0
    }
  },
  "transform": [
    {
      "calculate": "format(datum.value, '$,.2f')",
      "as": "usd"
    }
  ]
}"}}

