{"title":"결제 일별 추이 (건수 · 금액)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": "none",
  "padding": {
    "left": 30,
    "top": 30,
    "right": 46,
    "bottom": 22
  },
  "config": {
    "kibana": {
      "renderer": "svg"
    }
  },
  "signals": [
    {
      "name": "width",
      "init": "max(containerSize()[0] - 80, 120)",
      "on": [
        {
          "events": {
            "source": "window",
            "type": "resize"
          },
          "update": "max(containerSize()[0] - 80, 120)"
        },
        {
          "events": "timer{1000}",
          "update": "max(containerSize()[0] - 80, 120)"
        }
      ]
    },
    {
      "name": "height",
      "init": "max(containerSize()[1] - 60, 80)",
      "on": [
        {
          "events": {
            "source": "window",
            "type": "resize"
          },
          "update": "max(containerSize()[1] - 60, 80)"
        },
        {
          "events": "timer{1000}",
          "update": "max(containerSize()[1] - 60, 80)"
        }
      ]
    },
    {
      "name": "labelStep",
      "update": "max(1, ceil(length(domain('x')) * 42 / width))"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "dev-example-project-game",
        "body": {
          "size": 0,
          "runtime_mappings": {
            "iap_order_id": {
              "type": "keyword",
              "script": {
                "source": "def b = params._source?.data?.requestBody; if (b == null) return; String s = b.toString(); int i = s.indexOf('\"orderId\":'); if (i < 0) return; int p = i + 10; while (p < s.length() && s.charAt(p) == (char)' ') p++; int st = p; while (p < s.length() && Character.isDigit(s.charAt(p))) p++; if (p > st) emit(s.substring(st, p));"
              }
            },
            "usd_list_price": {
              "type": "double",
              "script": {
                "source": "def b = params._source?.data?.requestBody; if (b == null) return; String s = b.toString(); int i = s.indexOf('\"marketProductId\":\"'); if (i < 0) return; int st = i + 19; int e = s.indexOf('\"', st); if (e < 0) return; String pid = s.substring(st, e); int k = pid.lastIndexOf('pack.'); if (k < 0) return; try { emit(Double.parseDouble(pid.substring(k + 5))); } catch (Exception ex) {}"
              }
            }
          },
          "aggs": {
            "pay": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.requestPath.keyword": "/internal/iap/deliver"
                      }
                    },
                    {
                      "term": {
                        "data.statusCode": 200
                      }
                    },
                    {
                      "match_phrase": {
                        "data.requestBody": "\"payEnv\":\"test\""
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "days": {
                  "date_histogram": {
                    "field": "@timestamp",
                    "calendar_interval": "1d",
                    "time_zone": "Asia/Shanghai",
                    "min_doc_count": 0,
                    "extended_bounds": {
                      "min": {
                        "%timefilter%": "min"
                      },
                      "max": {
                        "%timefilter%": "max"
                      }
                    }
                  },
                  "aggs": {
                    "cnt": {
                      "cardinality": {
                        "field": "iap_order_id",
                        "precision_threshold": 40000
                      }
                    },
                    "orders": {
                      "terms": {
                        "field": "iap_order_id",
                        "size": 10000
                      },
                      "aggs": {
                        "usd": {
                          "max": {
                            "field": "usd_list_price"
                          }
                        }
                      }
                    },
                    "amount": {
                      "sum_bucket": {
                        "buckets_path": "orders>usd"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.pay.days.buckets"
      }
    },
    {
      "name": "table",
      "source": "raw",
      "transform": [
        {
          "type": "formula",
          "as": "day",
          "expr": "utcFormat(datum.key + 9*3600*1000, '%m/%d')"
        },
        {
          "type": "formula",
          "as": "dayFull",
          "expr": "utcFormat(datum.key + 9*3600*1000, '%Y-%m-%d')"
        },
        {
          "type": "formula",
          "as": "orderCount",
          "expr": "datum.cnt.value"
        },
        {
          "type": "formula",
          "as": "usd",
          "expr": "datum.amount && datum.amount.value ? datum.amount.value : 0"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "band",
      "domain": {
        "data": "table",
        "field": "day"
      },
      "range": "width",
      "paddingInner": 0.3,
      "paddingOuter": 0.15
    },
    {
      "name": "yCnt",
      "type": "linear",
      "domain": {
        "data": "table",
        "field": "orderCount"
      },
      "range": "height",
      "nice": true,
      "zero": true,
      "domainMin": 0
    },
    {
      "name": "yUsd",
      "type": "linear",
      "domain": {
        "data": "table",
        "field": "usd"
      },
      "range": "height",
      "nice": true,
      "zero": true,
      "domainMin": 0
    },
    {
      "name": "legend",
      "type": "ordinal",
      "domain": [
        "결제 건수",
        "결제 금액 (USD)"
      ],
      "range": [
        "#54B399",
        "#6092C0"
      ]
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "x",
      "ticks": false,
      "domain": false,
      "labelColor": "#69707d",
      "labelFontSize": 10,
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "round(datum.index * (length(domain('x')) - 1)) % labelStep === 0 ? datum.label : ''"
            }
          }
        }
      }
    },
    {
      "orient": "left",
      "scale": "yCnt",
      "tickMinStep": 1,
      "format": "d",
      "grid": true,
      "gridColor": "#69707d",
      "gridOpacity": 0.15,
      "domain": false,
      "ticks": false,
      "labelColor": "#54B399",
      "labelFontSize": 10,
      "tickCount": 5
    },
    {
      "orient": "right",
      "scale": "yUsd",
      "format": "$,.0f",
      "domain": false,
      "ticks": false,
      "labelColor": "#6092C0",
      "labelFontSize": 10,
      "tickCount": 5
    }
  ],
  "legends": [
    {
      "fill": "legend",
      "orient": "none",
      "legendX": -22,
      "legendY": -28,
      "direction": "horizontal",
      "symbolType": "circle",
      "labelColor": "#69707d",
      "labelFontSize": 11,
      "columnPadding": 14
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "table"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "day"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "y": {
            "scale": "yCnt",
            "field": "orderCount"
          },
          "y2": {
            "scale": "yCnt",
            "value": 0
          },
          "fill": {
            "value": "#54B399"
          },
          "cornerRadiusTopLeft": {
            "value": 2
          },
          "cornerRadiusTopRight": {
            "value": 2
          },
          "tooltip": {
            "signal": "{'날짜':datum.dayFull,'결제 건수':datum.orderCount,'결제 금액 (USD)':format(datum.usd,'$,.2f')}"
          }
        }
      }
    },
    {
      "type": "line",
      "from": {
        "data": "table"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "day",
            "band": 0.5
          },
          "y": {
            "scale": "yUsd",
            "field": "usd"
          },
          "stroke": {
            "value": "#6092C0"
          },
          "strokeWidth": {
            "value": 2.5
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "table"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "day",
            "band": 0.5
          },
          "y": {
            "scale": "yUsd",
            "field": "usd"
          },
          "size": {
            "value": 30
          },
          "fill": {
            "value": "#6092C0"
          },
          "tooltip": {
            "signal": "{'날짜':datum.dayFull,'결제 건수':datum.orderCount,'결제 금액 (USD)':format(datum.usd,'$,.2f')}"
          }
        }
      }
    }
  ]
}"}}

{"title":"국가별 PayRate (누적, 결제 유저 ÷ 전체 유저)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": "none",
  "padding": {
    "left": 64,
    "top": 22,
    "right": 16,
    "bottom": 6
  },
  "config": {
    "kibana": {
      "renderer": "svg"
    }
  },
  "signals": [
    {
      "name": "width",
      "init": "max(containerSize()[0] - 96, 200)",
      "on": [
        {
          "events": {
            "source": "window",
            "type": "resize"
          },
          "update": "max(containerSize()[0] - 96, 200)"
        },
        {
          "events": "timer{1000}",
          "update": "max(containerSize()[0] - 96, 200)"
        }
      ]
    },
    {
      "name": "rowCount",
      "update": "length(data('table'))"
    },
    {
      "name": "height",
      "update": "max(rowCount, 1) * 34 + 30"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "index": "dev-example-project-game",
        "body": {
          "size": 0,
          "aggs": {
            "byUser": {
              "terms": {
                "field": "data.userId",
                "size": 20000
              },
              "aggs": {
                "cc": {
                  "terms": {
                    "field": "data.countryCode.keyword",
                    "size": 1
                  }
                },
                "pay": {
                  "filter": {
                    "bool": {
                      "filter": [
                        {
                          "term": {
                            "data.requestPath.keyword": "/internal/iap/deliver"
                          }
                        },
                        {
                          "term": {
                            "data.statusCode": 200
                          }
                        },
                        {
                          "match_phrase": {
                            "data.requestBody": "\"payEnv\":\"test\""
                          }
                        }
                      ]
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.byUser.buckets"
      }
    },
    {
      "name": "table",
      "source": "raw",
      "transform": [
        {
          "type": "formula",
          "as": "country",
          "expr": "length(datum.cc.buckets) > 0 ? datum.cc.buckets[0].key : '미확인'"
        },
        {
          "type": "formula",
          "as": "paid",
          "expr": "datum.pay.doc_count > 0 ? 1 : 0"
        },
        {
          "type": "aggregate",
          "groupby": [
            "country"
          ],
          "ops": [
            "count",
            "sum"
          ],
          "fields": [
            null,
            "paid"
          ],
          "as": [
            "userCount",
            "payUsers"
          ]
        },
        {
          "type": "formula",
          "as": "payRate",
          "expr": "datum.userCount > 0 ? datum.payUsers / datum.userCount : 0"
        },
        {
          "type": "formula",
          "as": "label",
          "expr": "format(datum.payRate,'.1%') + '   ' + datum.payUsers + ' / ' + format(datum.userCount, ',') + '명'"
        },
        {
